const $=id=>document.getElementById(id);
const LEVELS=[
 {title:'O animal esquecido',description:'Encontre o único animal que recebeu zero refeições hoje. Sua consulta deve retornar apenas esse animal, identificado pelo nome ou id.',hints:['Há animais com a rotina incompleta, mas isso não significa que ficaram sem comida.','Compare a quantidade de refeições. Você procura quem não recebeu nenhuma.'],sql:'SELECT id, animal, especie, vezes_alimentado\nFROM animais\nWHERE vezes_alimentado = 0;',explanation:'WHERE filtra os registros pela condição desejada. Zero refeições identifica quem não foi alimentado.'},
 {title:'O veterano do zoológico',description:'Descubra qual animal é o mais velho do zoológico. Retorne somente esse animal, com seu nome ou id. A coluna idade guarda a idade em anos.',hints:['O veterano pode pertencer a uma espécie que vive muito mais tempo do que outras.','Você precisa comparar as idades de todos os animais, não apenas de uma espécie.'],sql:'SELECT id, animal, idade\nFROM animais\nORDER BY idade DESC\nLIMIT 1;',explanation:'DESC coloca as maiores idades primeiro. LIMIT 1 mantém apenas o animal mais velho. Uma consulta com MAX(idade) também pode funcionar, se retornar sua identificação.'},
 {title:'Os três caçulas',description:'Encontre os três animais mais novos do zoológico e mostre-os em ordem crescente de idade: do mais novo ao menos novo. Inclua o nome ou id de cada um.',hints:['Procure as menores idades de todo o zoológico.','Escolher três animais e ordená-los são duas partes do desafio. O primeiro deve ser o mais novo.'],sql:'SELECT id, animal, idade\nFROM animais\nORDER BY idade ASC\nLIMIT 3;',explanation:'ASC organiza do menor para o maior. LIMIT 3 mantém os três primeiros, que são os animais mais novos.'},
 {title:'Os veteranos, em outra ordem',description:'Selecione os três animais mais velhos do zoológico. Depois, apresente esses três em ordem crescente de idade: do menos velho ao mais velho. Inclua nome ou id.',hints:['Ordenar todo o zoológico em ordem crescente e pegar três registros encontra os mais novos — não os veteranos.','Primeiro escolha quem faz parte do grupo dos três mais velhos; só depois organize esse grupo em ordem crescente.'],sql:'SELECT id, animal, idade\nFROM (\n  SELECT id, animal, idade\n  FROM animais\n  ORDER BY idade DESC\n  LIMIT 3\n) AS veteranos\nORDER BY idade ASC;',explanation:'A consulta interna seleciona os três mais velhos. A externa organiza somente esse grupo em ordem crescente. CTEs e outras consultas equivalentes também são aceitas.'},
 {title:'Os dois gigantes',description:'Encontre os dois animais mais pesados de todo o zoológico. A coluna kg guarda o peso em quilogramas. Inclua nome ou id; a ordem entre os dois é livre.',hints:['O nome da espécie é uma pista, mas são os pesos individuais que confirmam os dois gigantes.','Compare os pesos de todos os animais e mantenha somente os dois maiores.'],sql:'SELECT id, animal, kg\nFROM animais\nORDER BY kg DESC\nLIMIT 2;',explanation:'DESC coloca os maiores pesos primeiro. LIMIT 2 retorna somente os dois animais mais pesados.'}
];
const ANSWER_GUIDES=[
 ['Comece com SELECT e inclua animal ou id para identificar o resultado. Você também pode mostrar vezes_alimentado para conferir.', 'Use FROM animais para escolher a tabela correta.', 'Com WHERE, mantenha somente os registros cujo contador de alimentação é igual a zero. Use = para comparar números; não coloque o nome da coluna entre aspas simples.'],
 ['Escolha animal e idade com SELECT e consulte a tabela animais.', 'Organize pela coluna idade, do maior número para o menor. ORDER BY idade DESC faz essa organização.', 'Use LIMIT 1 para manter só o primeiro registro. Consultar apenas MAX(idade) retorna a idade, mas não identifica o animal.'],
 ['Selecione animal e idade da tabela animais.', 'Para encontrar os mais novos, organize as idades da menor para a maior com ORDER BY idade ASC.', 'Depois da ordenação, LIMIT 3 mantém os três mais novos. Aplicar o limite antes de escolher os menores pode pegar animais diferentes.'],
 ['Resolva primeiro a seleção do grupo: organize as idades da maior para a menor e mantenha três registros.', 'Coloque essa seleção dentro de uma subconsulta no FROM, dando ao grupo o nome veteranos.', 'Na consulta externa, selecione o grupo e organize idade ASC. Assim você mostra os três mais velhos do menos velho para o mais velho. Uma CTE com WITH também pode organizar essas duas tarefas.'],
 ['Escolha animal e kg para identificar os animais e conferir seus pesos na tabela animais.', 'Ordene pela coluna kg, da maior para a menor, usando ORDER BY kg DESC.', 'Use LIMIT 2 para manter os dois maiores pesos. Filtrar só pela espécie não garante que você encontrou os dois indivíduos mais pesados.']
];
let SQL,db,target,level=0,won=false,consultas=0,pistas=0,history=[];
function message(text,type=''){$('feedback').textContent=text;$('feedback').className=type;}
function drawLevel(){
 $('steps').replaceChildren();LEVELS.forEach((l,i)=>{const d=document.createElement('div');d.className='step'+(i===level?' active':'');const b=document.createElement('b');b.textContent=i<level||i===level&&won?'✓':i+1;const s=document.createElement('span');s.textContent=l.title;d.append(b,s);$('steps').append(d);});
 $('mission-number').textContent=`NÍVEL ${level+1} DE ${LEVELS.length}`;$('mission-title').textContent=LEVELS[level].title;$('mission-text').textContent=LEVELS[level].description;
 $('hint').disabled=won||pistas>=2;$('hint').textContent=pistas>=2?'Duas pistas consultadas':'💡 Preciso de uma pista';
}
function render(results){$('results').replaceChildren();if(!results.length){$('row-count').textContent='0 registros';$('results').textContent='Nenhum registro encontrado. Revise sua consulta.';return;}const r=results[0];$('row-count').textContent=`${r.values.length} registro${r.values.length===1?'':'s'}`;const table=document.createElement('table'),head=document.createElement('thead'),tr=document.createElement('tr');r.columns.forEach(c=>{const th=document.createElement('th');th.textContent=c;tr.append(th);});head.append(tr);table.append(head);const body=document.createElement('tbody');r.values.forEach(row=>{const tr=document.createElement('tr');row.forEach(v=>{const td=document.createElement('td');td.textContent=v===null?'NULL':String(v);tr.append(td);});body.append(tr);});table.append(body);$('results').append(table);}
function expectedAnimals(){const all=ANIMAIS.slice();if(level===0)return [target];if(level===1)return all.sort((a,b)=>b.idade-a.idade).slice(0,1);if(level===2)return all.sort((a,b)=>a.idade-b.idade).slice(0,3);if(level===3)return all.sort((a,b)=>b.idade-a.idade).slice(0,3).sort((a,b)=>a.idade-b.idade);return all.sort((a,b)=>b.kg-a.kg).slice(0,2);}
function resultIds(r,q){
 const idColumns=new Set(['id']);for(const match of q.matchAll(/\bid\s+AS\s+["`\[]?(\w+)/gi))idColumns.add(match[1].toLowerCase());
 return r.values.map(row=>{
  const names=row.filter(v=>typeof v==='string'&&ANIMAIS.some(a=>a.animal===v));const byName=names.length===1?ANIMAIS.find(a=>a.animal===names[0]):null;
  const ix=r.columns.findIndex(c=>idColumns.has(c.toLowerCase()));const byId=ix>=0?ANIMAIS.find(a=>a.id===row[ix]):null;
  if(byName&&byId&&byName.id!==byId.id)return null;
  return (byName||byId)?.id??null;
 });
}
function correct(r,q){if(!r)return false;const expected=expectedAnimals().map(a=>a.id);if(r.values.length!==expected.length)return false;const ids=resultIds(r,q);if(new Set(ids).size!==expected.length||ids.includes(null))return false;return level===2||level===3?ids.every((id,i)=>id===expected[i]):expected.every(id=>ids.includes(id));}
function celebrate(){won=true;history[level]={consultas,pistas};$('celebration').hidden=false;$('winner-name').textContent=level===0?`Você encontrou ${target.animal}!`:'Resultado correto!';$('winner-details').textContent=`Nível ${level+1} concluído com ${consultas} consulta${consultas===1?'':'s'} e ${pistas} pista${pistas===1?'':'s'}. Sua consulta foi aceita pelo resultado.`;$('suggested-query').textContent=LEVELS[level].sql;$('suggested-explanation').textContent=LEVELS[level].explanation;$('next').hidden=level===LEVELS.length-1;$('finish').hidden=level!==LEVELS.length-1;$('rescue').hidden=level!==0;if(level===0)care();if(level===LEVELS.length-1){$('finish').textContent=`🏅 Você concluiu os cinco níveis! Total: ${history.reduce((s,h)=>s+h.consultas,0)} consultas e ${history.reduce((s,h)=>s+h.pistas,0)} pistas. Clique em Recomeçar para jogar novamente.`;}drawLevel();message('Parabéns! Você resolveu este nível. 🏆','success');}
function cleanSQL(q){return q.replace(/'(?:''|[^'])*'/g,"''").replace(/\/\*[\s\S]*?\*\//g,' ').replace(/--[^\n]*/g,' ');}
function execute(){const q=$('query').value.trim();if(!q){message('Digite sua consulta SQL.','error');return;}let readDb;try{const safe=cleanSQL(q);if(!/^\s*(SELECT|WITH)\b/i.test(safe))throw Error('Use SELECT ou uma consulta com WITH para pesquisar.');if(/\b(?:INSERT|UPDATE|DELETE|DROP|ALTER|CREATE|ATTACH|DETACH|PRAGMA|REPLACE)\b/i.test(safe))throw Error('O editor aceita apenas consultas de leitura.');readDb=new SQL.Database(db.export());let count=0;for(const stmt of readDb.iterateStatements(q))count++;if(count!==1)throw Error('Execute apenas uma consulta por vez.');const result=readDb.exec(q);if(!won)consultas++;render(result);if(correct(result[0],q)){if(!won)celebrate();else message('Consulta equivalente aceita. O resultado continua correto!','success');}else message('Consulta executada. Confira quais animais apareceram, a quantidade e a ordem pedida. Inclua nome ou id para identificar cada animal.');}catch(e){message('Vamos ajustar: '+e.message,'error');}finally{if(readDb)readDb.close();}}
function counter(){return db.exec(`SELECT vezes_alimentado FROM animais WHERE id=${target.id}`)[0].values[0][0];}
function care(){const n=counter();$('rescue-text').textContent=`${target.animal} · ${target.especie} · ${n} de 3 refeições registradas hoje.`;$('feed').disabled=n>=3;$('feed').textContent=n>=3?'Três refeições registradas ✓':'Registrar uma alimentação (+1)';}
$('run').onclick=execute;$('hint').onclick=()=>{if(won||pistas>=2)return;$('hint-text').hidden=false;$('hint-text').textContent=LEVELS[level].hints[pistas++];drawLevel();};
$('example').onclick=()=>{$('hint-text').hidden=false;$('hint-text').textContent='SELECT escolhe as colunas, FROM informa a tabela e WHERE aplica uma condição. ORDER BY organiza os registros e LIMIT restringe a quantidade. Você decide como combinar esses comandos.';};
$('answer').onclick=()=>{const panel=$('answer-panel');panel.hidden=!panel.hidden;$('answer').setAttribute('aria-expanded',String(!panel.hidden));if(panel.hidden)return;$('answer-steps').replaceChildren();for(const text of ANSWER_GUIDES[level]){const li=document.createElement('li');li.textContent=text;$('answer-steps').append(li);}$('answer-query').textContent=LEVELS[level].sql;$('answer-explanation').textContent=LEVELS[level].explanation;};
$('query').addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();if(db)execute();}});
$('feed').onclick=()=>{if(level!==0||!won)return;db.run(`UPDATE animais SET vezes_alimentado=vezes_alimentado+1 WHERE id=${target.id} AND vezes_alimentado<3`);care();message('Alimentação registrada. Você já pode avançar para o próximo nível.','success');};
function clearLevel(){$('answer-panel').hidden=true;$('answer-solution').open=false;$('answer').setAttribute('aria-expanded','false');won=false;consultas=0;pistas=0;$('query').value='';$('hint-text').hidden=true;$('celebration').hidden=true;$('rescue').hidden=true;$('finish').hidden=true;$('results').innerHTML='<div class="empty">🔎<p>Escolha sua consulta e descubra o resultado.</p></div>';$('row-count').textContent='Nenhuma consulta ainda';drawLevel();}
$('next').onclick=()=>{if(won&&level<LEVELS.length-1){level++;clearLevel();message('Novo nível liberado. Os dados do zoológico foram preservados.');}};
function reset(){if(db)db.close();db=new SQL.Database();db.run('CREATE TABLE animais (id INTEGER PRIMARY KEY, animal TEXT NOT NULL UNIQUE, especie TEXT NOT NULL, vezes_alimentado INTEGER NOT NULL CHECK(vezes_alimentado BETWEEN 0 AND 3), idade INTEGER NOT NULL CHECK(idade>0), kg REAL NOT NULL UNIQUE CHECK(kg>0))');target=ANIMAIS[Math.floor(Math.random()*ANIMAIS.length)];const stmt=db.prepare('INSERT INTO animais VALUES (?, ?, ?, ?, ?, ?)');for(const a of ANIMAIS)stmt.run([a.id,a.animal,a.especie,a.id===target.id?0:Math.max(1,a.vezes_alimentado),a.idade,a.kg]);stmt.free();level=0;history=[];clearLevel();message('Nível 1 pronto. Há exatamente um animal sem refeições.');}
$('restart').onclick=()=>{if(db&&confirm('Recomeçar os cinco níveis? O progresso e as refeições serão reiniciados.'))reset();};drawLevel();initSqlJs({locateFile:f=>'vendor/'+f}).then(engine=>{SQL=engine;reset();$('run').disabled=false;$('run').textContent='Executar consulta →';}).catch(()=>message('Não foi possível carregar o banco. Recarregue a página.','error'));
